                {
                    "record_index": records.index(record),
                    "record_id": record.get("id"),
                    "value": record[value_field],
                    "matched": any(
                        _json_equal(record[value_field], allowed)
                        for allowed in allowed_values
                    ),
                }
                for record in members
            ]
