            for earlier in seen_keys
        ):
            violations.append(
                _unique_key_violation(
                    rule,
                    index,
                    record,
                    fields,
                    key,
                    _DUPLICATE_KEY_MESSAGE,
                )
            )
        else:
            seen_keys.append(key)


