    # Each group keeps its key and ``(record_index, record)`` members;
    # enumeration guarantees JSON-correct locators and record-order
    # samples without falling back to Python ``list.index``.
    groups: Dict[str, Dict[str, Any]] = {}
    group_keys: List[List[Any]] = []

    for index, record in enumerate(records):
        group_values = [record.get(field) for field in group_fields]
        if any(value is None for value in group_values):
            continue
        if value_field not in record or record[value_field] is None:
            continue

        token = _canonical_json(group_values)
        group = groups.get(token)
        if group is None:
            group = {"key": group_values, "members": []}
            groups[token] = group
            group_keys.append(group_values)
        group["members"].append((index, record))

    # Groups report in fixed field order with JSON-ascending keys.
    group_keys.sort(
        key=lambda key: tuple(_json_sort_token(value) for value in key)
    )

    for group_values in group_keys:
        token = _canonical_json(group_values)
        members = groups[token]["members"]
        record_count = len(members)
        matched_members = [
            (index, record)
            for index, record in members
            if matches_allowed(record[value_field])
        ]
        matched_count = len(matched_members)
        ratio = matched_count / record_count
        if ratio >= min_ratio:
            continue

        first_index, first_record = members[0]
        samples = [
            {
                "record_index": member_index,
                "record_id": record.get("id"),
                "value": record[value_field],
                "matched": matches_allowed(record[value_field]),
            }
            for member_index, record in members
        ]
        violations.append(
            {
                "rule_id": rule["id"],
                "record_index": first_index,
                "record_id": first_record.get("id"),
                "group": [
                    {"field": field, "value": value}
                    for field, value in zip(group_fields, group_values)
                ],
                "record_count": record_count,
                "matched_count": matched_count,
                "ratio": ratio,
                "samples": samples,
            }
        )

    return len(groups)

