        self.assertEqual(proc.returncode, 0, proc.stderr)
        body = json.loads(proc.stdout.decode("utf-8"))
        self.assertEqual(
            body["violations"],
            [
                {
                    "rule_id": "uk",
                    "record_index": 1,
                    "record_id": "r2",
                    "fields": ["country", "city"],
                    "value": ["US", "NYC"],
                    "message": "is a duplicate unique key",
