                    "rule_id": "gr",
                    "record_index": 0,
                    "record_id": "r1",
                    "group": [
                        {"field": "country", "value": "US"},
                        {"field": "city", "value": "LA"},
                    ],
                    "record_count": 2,
                    "matched_count": 1,
                    "ratio": 0.5,
                    "samples": [
                        {
                            "record_index": 0,
                            "record_id": "r1",
                            "value": "bad",
                            "matched": False,
                        },
                        {
                            "record_index": 1,
                            "record_id": "r2",
                            "value": "ok",
