            {"id": "r2", "country": "US", "city": "LA", "status": "ok"},
        ]
        proc = run_json(payload(records, [RATIO_RULE]))
        self.assertEqual(proc.returncode, 0, proc.stderr)
        body = json.loads(proc.stdout.decode("utf-8"))
        self.assertEqual(
            body["violations"],
            [
                {
                    "rule_id": "gr",
                    "record_index": 0,
                    "record_id": "r1",
                    "group": [
                        {"field": "country", "value": "US"},
                        {"field": "city", "value": "LA"},
                    ],
                    "record_count": 2,
                    "matched_count": 1,
                    "ratio": 0.5,
